window.docContents[182].resolve({"/Environment/#envOverview":{"contents":"The cvc5 types for terms, sorts, solvers, etc. are all related to a notion of (term) manager\n responsible for allocating and indexing terms and sorts. These types cannot\ninteract and will produce a runtime error if they do not agree on their manager.\n\n\n\n\n\n","context":"Cvc.lean -- High-Level CVC5 API","header":"2. Environment","id":"/Environment/#envOverview"}});